declare(strict_types=1);define('_GNUBOARD_',true);require dirname(__DIR__,2).'/bridge/taxonomy-admin.php';require dirname(__DIR__,2).'/bridge/taxonomy-guard.php';require dirname(__DIR__,2).'/bridge/home-store.php';require dirname(__DIR__,2).'/bridge/world-mv.php';
function must($x,$why){if(!$x)throw new RuntimeException($why);}
$db=new PDO('mysql:host=127.0.0.1;dbname=noa_restore_verification;charset=utf8mb4','root','noa-isolated-only',[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_EMULATE_PREPARES=>false]);
$before=nt_legacy_guard($db);$protected=nt_release_guard($db,$before);$simulated=$protected;$simulated['historicalVisits']['new-visit']='new-fingerprint';if($simulated['visitCounts']){$day=array_key_first($simulated['visitCounts']);$simulated['visitCounts'][$day]++;}must(!nt_release_changes($protected,$simulated),'normal append-only telemetry blocked');$damaged=$protected;$damaged['stable']['g5_config']['rows']++;must(nt_release_changes($protected,$damaged)!==[],'configuration protection bypassed');if($protected['historicalVisits']){$damaged=$protected;unset($damaged['historicalVisits'][array_key_first($damaged['historicalVisits'])]);must(nt_release_changes($protected,$damaged)!==[],'historical visit deletion ignored');}$inventory=nt_inventory($db);$beforeHome=nh_load($db,ny_latest($db));$beforeWorld=nwm_load($db,ny_songs($db,ny_batch($db)));$migration=nt_migrate($db,'isolated-test');$one=nt_sync($db,'isolated-test');$logs=(int)$db->query('SELECT COUNT(*) FROM noa_classification_logs')->fetchColumn();$two=nt_sync($db,'isolated-test');must($two['replayed']&&$logs===(int)$db->query('SELECT COUNT(*) FROM noa_classification_logs')->fetchColumn(),'identical input not idempotent');
$counts=nt_counts($db);$revisions=(int)$db->query('SELECT COUNT(*) FROM noa_production_rule_revisions')->fetchColumn();$repeat=nt_migrate($db,'isolated-test');must(!$repeat['created']&&$repeat['productionRules']['imported']===0,'migration/import replay created duplicate data');must($revisions===(int)$db->query('SELECT COUNT(*) FROM noa_production_rule_revisions')->fetchColumn(),'revision duplicates');
$rule=$db->query("SELECT * FROM noa_production_rules WHERE rule_id='common:unified'")->fetch(PDO::FETCH_ASSOC);$edited=$rule['body']."\nIsolated SQL precedence test.";nt_admin_save($db,['action'=>'save_production_rule','id'=>$rule['rule_id'],'revision'=>$rule['revision'],'body'=>$edited,'reason'=>'isolated verification'],'isolated-test');nt_migrate($db,'isolated-test');must(str_contains(nt_effective_rules($db,'kpop-original')['common']['productionGuidelines'],'Isolated SQL precedence test.'),'redeploy overwrote edited production rule');
$stale=false;try{nt_admin_save($db,['action'=>'save_production_rule','id'=>$rule['rule_id'],'revision'=>$rule['revision'],'body'=>'stale','reason'=>'test'],'test');}catch(DomainException $e){$stale=true;}must($stale,'stale edit accepted');
$cycle=false;try{nt_admin_save($db,['action'=>'save_category','id'=>'kpop-original','name'=>'KPOP','parent'=>'original','revision'=>1,'enabled'=>true,'reason'=>'test'],'test');}catch(DomainException $e){$cycle=true;}must($cycle,'cyclic category allowed');
$after=nt_legacy_guard($db);must($before===$after,'preexisting data changed');$home=nh_load($db,ny_latest($db));foreach(['stories','covers','playlists']as $section){must(count($home[$section])===count($beforeHome[$section]),'home section regressed:'.$section);must(array_column($home[$section],'videoId')===array_column($beforeHome[$section],'videoId'),'home top ranking changed:'.$section);}
$world=nwm_load($db,ny_songs($db,ny_batch($db)));must($world['counts']['displayed']===$beforeWorld['counts']['displayed'],'official MV disappeared');
$savedRule=$db->query('SELECT rule_id,conditions FROM noa_classification_rules ORDER BY rule_id LIMIT 1')->fetch(PDO::FETCH_ASSOC);$q=$db->prepare('UPDATE noa_classification_rules SET conditions=? WHERE rule_id=?');$q->execute([nt_json(['kind'=>'invalid','values'=>['x']]),$savedRule['rule_id']]);$failed=false;try{nt_sync($db,'isolated-error-test');}catch(InvalidArgumentException $e){$failed=true;}must($failed,'invalid rule did not fail closed');must((int)$db->query("SELECT COUNT(*) FROM noa_classification_logs WHERE event='error'")->fetchColumn()>0,'failed synchronization not recorded durably');$q->execute([$savedRule['conditions'],$savedRule['rule_id']]);must(nt_legacy_guard($db)===$before,'failed sync modified original tables');
$report=['inventoryBefore'=>$inventory,'migration'=>$migration,'counts'=>$counts,'classification'=>$one,'releaseGuardSeparatesAppendOnlyTelemetry'=>true,'replaySafe'=>$two['replayed'],'failedSyncLoggedAndRolledBack'=>true,'allPreexistingTablesPreserved'=>true,'preservedTableCount'=>count($before),'productionRules'=>(int)$db->query('SELECT COUNT(*) FROM noa_production_rules')->fetchColumn(),'productionEditsSurviveRedeploy'=>true,'homeCounts'=>array_map(fn($s)=>count($home[$s]),['stories','covers','playlists']),'world'=>$world['counts'],'catalogVersions'=>$db->query('SELECT version_name,language,COUNT(*) n FROM noa_catalog_songs GROUP BY version_name,language')->fetchAll(PDO::FETCH_ASSOC),'unmatchedWorld'=>array_values(array_map(fn($r)=>['videoId'=>$r['videoId'],'title'=>$r['title'],'ep'=>$r['ep']],array_filter($world['videos'],fn($r)=>!$r['songId']))),'confirmedByGenre'=>$db->query("SELECT s.genre_id,COUNT(*) n FROM noa_content_matches m JOIN noa_catalog_songs s ON s.song_id=m.song_id WHERE m.status='confirmed' GROUP BY s.genre_id")->fetchAll(PDO::FETCH_ASSOC)];
@mkdir('quality-taxonomy',0700,true);file_put_contents('quality-taxonomy/report.json',nt_json($report));file_put_contents('quality-taxonomy/public.json',nt_json(nt_public_data($db)));file_put_contents('quality-taxonomy/admin-fixture.json',nt_json(nt_admin_status($db)));echo 'NOA_TAXONOMY_VERIFIED '.nt_json($report)."\n";
